ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output' / 'pdf'
OUT.mkdir(parents=True, exist_ok=True)
pdfmetrics.registerFont(TTFont('ArialQ', 'C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialQB', 'C:/Windows/Fonts/arialbd.ttf'))
INK = HexColor('#26183E'); BLUE = HexColor('#D8E9F2'); PAPER = HexColor('#F8F6F0'); GRAY = HexColor('#5A5764')
styles = {
 'kicker': ParagraphStyle('kicker',fontName='ArialQB',fontSize=10,leading=14,textColor=GRAY,spaceAfter=12),
 'title': ParagraphStyle('title',fontName='ArialQB',fontSize=27,leading=31,textColor=INK,spaceAfter=12),
 'lead': ParagraphStyle('lead',fontName='ArialQ',fontSize=12,leading=17,textColor=INK,spaceAfter=14),
 'h': ParagraphStyle('h',fontName='ArialQB',fontSize=14,leading=18,textColor=INK,spaceBefore=11,spaceAfter=6,keepWithNext=True),
 'body': ParagraphStyle('body',fontName='ArialQ',fontSize=10,leading=14,textColor=INK,spaceAfter=6),
 'small': ParagraphStyle('small',fontName='ArialQ',fontSize=8.5,leading=12,textColor=GRAY,spaceAfter=6),
 'cell': ParagraphStyle('cell',fontName='ArialQ',fontSize=9.5,leading=13.5,textColor=INK),
 'cellb': ParagraphStyle('cellb',fontName='ArialQB',fontSize=9.5,leading=13.5,textColor=INK),
}

def p(text, style='body'):
 return Paragraph(escape(text).replace('\n','<br/>'),styles[style])

def table(rows, widths):
 data=[[p(str(c),'cellb' if i==0 else 'cell') for c in row] for i,row in enumerate(rows)]
 t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.4,HexColor('#D8D5DF'))]))
 return t

def draw_page(c,doc):
 w,h=doc.pagesize
 c.setFillColor(PAPER); c.rect(0,0,w,h,fill=1,stroke=0)
 c.setFillColor(INK); c.rect(42,h-33,22,5,fill=1,stroke=0)
 c.setFont('ArialQB',9); c.drawString(73,h-33,'QADAM / AI HACK 2026')
 c.setStrokeColor(HexColor('#D8D5DF')); c.line(42,47,w-42,47)
 c.setFillColor(GRAY); c.setFont('ArialQ',7.5)
 c.drawString(42,33,'УЧЕБНЫЙ ПРИМЕР · ВЫМЫШЛЕННОЕ МЕРОПРИЯТИЕ · v1.0 / 08.11.2026')
 c.drawRightString(w-42,33,str(doc.page))

def document(filename, label, pages):
 story=[]
 for idx,page in enumerate(pages):
  if idx: story.append(PageBreak())
  story.extend([p(label,'kicker'),p(page['title'],'title')])
  if page.get('lead'): story.append(p(page['lead'],'lead'))
  for block in page['blocks']:
   if isinstance(block,tuple): story.extend([p(block[0],'h'),p(block[1])])
   elif isinstance(block,dict): story.append(table(block['rows'],block['widths'])); story.append(Spacer(1,10))
   else: story.append(p(block))
 doc=SimpleDocTemplate(str(OUT/filename),pagesize=(595.28,841.89),leftMargin=42,rightMargin=42,topMargin=63,bottomMargin=65,title='QADAM AI HACK 2026 - '+label,author='OpenFacto / учебный сценарий')
 doc.build(story,onFirstPage=draw_page,onLaterPages=draw_page)
 return {'filename':filename,'title':'QADAM AI HACK 2026 - '+label,'pages':pages}

